<?php declare(strict_types=1); namespace Database\Seeders; use Core\Database\Seeding\Seeder; class RoleSeeder extends Seeder { public function run(): void { $roles = [ ['name' => 'admin', 'description' => 'Full access to every module.'], ['name' => 'editor', 'description' => 'Manages content, products and media.'], ['name' => 'viewer', 'description' => 'Read-only access.'], ]; foreach ($roles as $role) { if (!$this->db->table('roles')->where('name', $role['name'])->exists()) { $this->db->insert('roles', $role + [ 'created_at' => date('Y-m-d H:i:s'), 'updated_at' => date('Y-m-d H:i:s'), ]); } } } } 